      stT.setContext(ctx).draw(); if(stB){ stB.setContext(ctx).draw(); new VF.StaveConnector(stT,stB).setType(VF.StaveConnector.type.BRACE).setContext(ctx).draw(); new VF.StaveConnector(stT,stB).setType(VF.StaveConnector.type.SINGLE_LEFT).setContext(ctx).draw(); if(o.i===score.nBars-1) new VF.StaveConnector(stT,stB).setType(VF.StaveConnector.type.BOLD_DOUBLE_RIGHT).setContext(ctx).draw(); }
