            const y=ys[ki];let half=9;ys.forEach((other,j)=>{if(j!==ki&&Math.abs(other-y)>.1)half=Math.min(half,Math.abs(other-y)/2);});
            hit.setAttribute('x',left-5);hit.setAttribute('y',y-half);hit.setAttribute('width',Math.max(20,right-left+10));hit.setAttribute('height',half*2);
            hit.setAttribute('class','score-hit');hit.setAttribute('fill','transparent');hit.setAttribute('stroke','none');
            hit.setAttribute('tabindex','0');hit.setAttribute('role','button');hit.setAttribute('aria-label',pName(pitch)+' · 눌러서 편집');
